#include <queue>
#include <stack>
#include <deque>
#include <map>
#include <set>
#include <unordered_map>
#include <unordered_set>
#include <functional>
#include <numeric>
#include <sstream>
#include <iostream>
using namespace std;
int main(){int n,k;scanf("%d %d",&n,&k);vector<long long>a(n);
for(int i=0;i<n;++i)scanf("%lld",&a[i]);
bool first=true;
for(int i=0;i+k<=n;++i){
vector<long long>w(a.begin()+i,a.begin()+i+k);
sort(w.begin(),w.end());
if(!first)printf(" ");printf("%lld",w[(k-1)/2]);first=false;}
printf("\n");return 0;}

